// Parse the AI response; fall back to a review-needed flag if it doesn't parse.
const raw = $input.first().json.message?.content ?? $input.first().json.text ?? $input.first().json.output ?? '';

let parsed;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
  parsed.parseFailed = false;
} catch (e) {
  parsed = { summary: '', actionItems: [], decisions: [], parseFailed: true };
}

const meeting = $('Parse Meeting Transcript').first().json;
const config = $('Prepare Configs').first().json;

return [{
  json: {
    ...meeting,
    ...parsed,
    ...config
  }
}];

