// Turn one AI response's list of action items into individual n8n items —
// one item per action item, so the next node runs once per task automatically.
const item = $('Parse Action Items JSON').first().json;
const actionItems = item.actionItems || [];

if (actionItems.length === 0) {
  return [];
}

return actionItems.map(ai => ({
  json: {
    task: ai.task,
    owner: ai.owner || 'Unassigned',
    dueDate: ai.dueDate || '',
    meetingTitle: item.meetingTitle,
    meetingDate: item.meetingDate,
    notionDatabaseId: item.notionDatabaseId
  }
}));
